        reset <= '0';
        wait until falling_edge(clk);
        
        start <= '1';
        wait for CLK_PER;
        start <= '0';
        
        wait until done = '1';
        
        report "--- PERFORMANCE REPORT ---";
        report "Configuration: 32x32 at 16-bit";
        report "Python Predicted Latency: " & integer'image(expected_latency);
        report "Hardware Measured Latency: " & integer'image(latency_counter);
        
        if (latency_counter = expected_latency) then
            report "VERIFICATION SUCCESS";
        else
            report "VERIFICATION FAILED";
        end if;
        wait; 
    end process;

